reference_solution:
def minimum_garden_perimeter(needed_apples):
    def apples(radius):
        return 2 * radius * (radius + 1) * (2 * radius + 1)
    lower, upper = 0, 1
    while apples(upper) < needed_apples:
        upper *= 2
    while lower < upper:
        middle = (lower + upper) // 2
        if apples(middle) >= needed_apples:
            upper = middle
        else:
            lower = middle + 1
    return 8 * lower

